package game

import (
	"errors"
	"fmt"
	"strconv"
)

// Class skins are purely cosmetic: six armour tiers per class and a set of colour
// variants (dyes), earned through class mastery. They never change run power. The
// art for every class/tier/variant combination is generated by
// scripts/pixel-art/heroes.mjs; tier numbers and variant IDs must match it.

var (
	ErrInvalidSkin = errors.New("unknown armour tier or colour variant")
	ErrSkinLocked  = errors.New("that look is not unlocked yet: keep playing this class to earn it")
)

const (
	MinSkinTier       = 1
	MaxSkinTier       = 6
	DefaultSkinTier   = 1
	DefaultSkinColour = "heraldic"
)

// PlayerSkin is a player's chosen look for their selected class.
type PlayerSkin struct {
	Tier    int    `json:"tier"`
	Variant string `json:"variant"`
}

// DefaultPlayerSkin is the look every class starts with.
func DefaultPlayerSkin() PlayerSkin {
	return PlayerSkin{Tier: DefaultSkinTier, Variant: DefaultSkinColour}
}

// SkinTierDefinition is one armour tier; Rank and MasteryLevel are shared by every
// class, Name and Description are the class's own set.
type SkinTierDefinition struct {
	Tier         int    `json:"tier"`
	Rank         string `json:"rank"`
	Name         string `json:"name"`
	Description  string `json:"description"`
	MasteryLevel int    `json:"masteryLevel"`
}

// SkinVariantDefinition is a colour variant that applies to every unlocked tier.
type SkinVariantDefinition struct {
	ID           string `json:"id"`
	Name         string `json:"name"`
	Description  string `json:"description"`
	MasteryLevel int    `json:"masteryLevel"`
}

// ClassSkinSet lists one class's armour tiers in order.
type ClassSkinSet struct {
	ClassID string               `json:"classId"`
	Tiers   []SkinTierDefinition `json:"tiers"`
}

// ClassSkinCatalog is the published shape of the skin rules.
type ClassSkinCatalog struct {
	Classes  []ClassSkinSet          `json:"classes"`
	Variants []SkinVariantDefinition `json:"variants"`
}

// The unlock ladder interleaves armour and dyes so most early mastery ranks bring
// something new: rank 2 armour, 3 dye, 4 armour, 6 dye, 7 armour, 9 dye, 11 armour,
// 16 the final armour and 20 the mythic dye.
var skinTierRanks = []struct {
	rank         string
	masteryLevel int
}{
	{"Recruit", 1}, {"Journeyman", 2}, {"Veteran", 4}, {"Champion", 7}, {"Exalted", 11}, {"Ascendant", 16},
}

