// ClassSkinCatalogSnapshot returns the skin rules for every class with art.
func ClassSkinCatalogSnapshot() ClassSkinCatalog {
	catalog := ClassSkinCatalog{Variants: append([]SkinVariantDefinition(nil), skinVariantCatalog...)}
	for _, class := range ClassCatalog() {
		if set, ok := classSkinTiers(class.ID); ok {
			catalog.Classes = append(catalog.Classes, ClassSkinSet{ClassID: class.ID, Tiers: set})
		}
	}
	return catalog
}

func classSkinTiers(classID string) ([]SkinTierDefinition, bool) {
	names, ok := classSkinSets[classID]
	if !ok {
		return nil, false
	}
	tiers := make([]SkinTierDefinition, 0, MaxSkinTier)
	for i, rank := range skinTierRanks {
		tiers = append(tiers, SkinTierDefinition{Tier: i + 1, Rank: rank.rank, Name: names[i][0], Description: names[i][1], MasteryLevel: rank.masteryLevel})
	}
	return tiers, true
}

func findSkinVariant(id string) (SkinVariantDefinition, bool) {
	for _, variant := range skinVariantCatalog {
		if variant.ID == id {
			return variant, true
		}
	}
	return SkinVariantDefinition{}, false
}

// SkinTierMasteryLevel is the class mastery level that unlocks an armour tier.
func SkinTierMasteryLevel(tier int) (int, bool) {
	if tier < MinSkinTier || tier > MaxSkinTier {
		return 0, false
	}
	return skinTierRanks[tier-1].masteryLevel, true
}

// ValidatePlayerSkin checks that a look exists and that the class mastery level
// has earned both its armour tier and its colour variant.
func ValidatePlayerSkin(skin PlayerSkin, masteryLevel int) error {
	tierLevel, ok := SkinTierMasteryLevel(skin.Tier)
	variant, variantOK := findSkinVariant(skin.Variant)
	if !ok || !variantOK {
		return ErrInvalidSkin
	}
	if masteryLevel < tierLevel || masteryLevel < variant.MasteryLevel {
		return ErrSkinLocked
	}
	return nil
}

// HighestUnlockedSkinTier is the best armour a class mastery level allows.
func HighestUnlockedSkinTier(masteryLevel int) int {
	best := DefaultSkinTier
	for i, rank := range skinTierRanks {
		if masteryLevel >= rank.masteryLevel {
			best = i + 1
		}
	}
	return best
}

func skinTierRewardID(classID string, tier int) string {
	return "armor." + classID + ".t" + strconv.Itoa(tier)
}

func skinVariantRewardID(classID, variantID string) string {
	return "dye." + classID + "." + variantID
}

// classSkinRewards adds each class's earnable armour tiers and dyes (everything
// past the starting look) to the profile collection.
func classSkinRewards() []ProfileRewardDefinition {
	var rewards []ProfileRewardDefinition
	for _, class := range ClassCatalog() {
		tiers, ok := classSkinTiers(class.ID)
		if !ok {
			continue
		}
		for _, tier := range tiers[1:] {
			rewards = append(rewards, ProfileRewardDefinition{
				ID: skinTierRewardID(class.ID, tier.Tier), Name: tier.Name, Category: "armor", ClassID: class.ID, ClassMasteryLevel: tier.MasteryLevel,
				Description: fmt.Sprintf("%s armour, tier %d (%s). %s", class.Name, tier.Tier, tier.Rank, tier.Description),
			})
		}
		for _, variant := range skinVariantCatalog[1:] {
			rewards = append(rewards, ProfileRewardDefinition{
				ID: skinVariantRewardID(class.ID, variant.ID), Name: variant.Name + " " + class.Name, Category: "dye", ClassID: class.ID, ClassMasteryLevel: variant.MasteryLevel,
				Description: fmt.Sprintf("A colour variant for every %s armour tier. %s", class.Name, variant.Description),
			})
		}
	}
	return rewards
}

// SelectPlayerSkin stores a validated look for the player's current class. The
// caller supplies the authoritative class mastery level from the player's profile.
func SelectPlayerSkin(room *Room, playerID string, skin PlayerSkin, masteryLevel int) error {
	if room.Run != nil {
		return ErrArchetypeLocked
	}
	if !contains(room.PlayerIDs, playerID) || room.Presence[playerID].LeftAt != nil {
		return ErrNotPlayer
	}
	if err := ValidatePlayerSkin(skin, masteryLevel); err != nil {
		return err
	}
	if room.PlayerSkins == nil {
		room.PlayerSkins = make(map[string]PlayerSkin)
	}
	room.PlayerSkins[playerID] = skin
	return nil
}
